-- Synchronizacja kategorii i podkategorii antyków
ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`), `position`=VALUES(`position`), `slug`=VALUES(`slug`), `name`=VALUES(`name`), `cost`=VALUES(`cost`), `thumb`=VALUES(`thumb`), `path`=VALUES(`path`), `content`=VALUES(`content`), `h1`=VALUES(`h1`), `title`=VALUES(`title`), `keywords`=VALUES(`keywords`), `description`=VALUES(`description`);
